import{_ as l,a0 as p,w as o,s as c,ao as d,I as n,x as i,a1 as t,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"如何在 Ubuntu 22.04 上安装 CRI-O 容器运行时 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 22.04 上安装 CRI-O 容器运行时 | LCTT (202304) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 22.04 上安装 CRI-O 容器运行时 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 22.04 上安装 CRI-O 容器运行时 | LCTT (202304) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202304/20230321.0 ⭐️⭐️ How to Install CRI-O (Container Runtime) on Ubuntu 22.04","title":"如何在 Ubuntu 22.04 上安装 CRI-O 容器运行时","tag":"202304","desc":""},"relativePath":"202304/20230321.0 ⭐️⭐️ How to Install CRI-O (Container Runtime) on Ubuntu 22.04.md","filePath":"[post].md"}'),r={name:"202304/20230321.0 ⭐️⭐️ How to Install CRI-O (Container Runtime) on Ubuntu 22.04.md"};function h(u,s,g,b,k,C){const a=p("Link");return o(),c("div",null,[s[15]||(s[15]=d(`<h1 id="如何在-ubuntu-22-04-上安装-cri-o-容器运行时" tabindex="-1">如何在 Ubuntu 22.04 上安装 CRI-O 容器运行时 <a class="header-anchor" href="#如何在-ubuntu-22-04-上安装-cri-o-容器运行时" aria-label="Permalink to “如何在 Ubuntu 22.04 上安装 CRI-O 容器运行时”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202304/03/105419akd0pr3ns2n50nz0.jpg" alt=""></p><p>CRI-O 是 Kubernetes 的开源轻量级容器运行时。它是使用 <ruby>开放容器组织<rt>Open Container Initiative</rt></ruby>（OCI）兼容运行时的 Kubernetes <ruby>容器运行时接口<rt>Container Runtime Interface</rt></ruby>（CRI）的实现。在运行 Kubernetes 时，它是 Docker 的完美替代品。</p><p>在本指南中，我们将逐步演示如何在 Ubuntu 22.04 LTS 上安装 CRI-O。</p><h3 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to “先决条件”">​</a></h3><p>在开始之前，这是你需要的：</p><ul><li>具有 SSH 访问权限的 Ubuntu 22.04 实例</li><li>在实例上配置的 sudo 用户</li><li>快速稳定的互联网连接</li></ul><p>有了这个，让我们开始吧。</p><h3 id="步骤-1-更新系统并安装依赖" tabindex="-1">步骤 1：更新系统并安装依赖 <a class="header-anchor" href="#步骤-1-更新系统并安装依赖" aria-label="Permalink to “步骤 1：更新系统并安装依赖”">​</a></h3><p>立即登录你的服务器实例，并按如下方式更新包列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt update</span></span></code></pre></div><p>更新本地包索引后，按如下方式安装依赖项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install apt-transport-https ca-certificates curl gnupg2 software-properties-common -y</span></span></code></pre></div><h3 id="步骤-2-添加-cri-o-存储库" tabindex="-1">步骤 2：添加 CRI-O 存储库 <a class="header-anchor" href="#步骤-2-添加-cri-o-存储库" aria-label="Permalink to “步骤 2：添加 CRI-O 存储库”">​</a></h3><p>要安装 CRI-O，我们需要在 Ubuntu 上添加或启用它的仓库。但首先，你需要根据操作系统和要安装的 CRI-O 版本定义变量。</p><p>因此，定义如下变量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ export OS=xUbuntu_22.04</span></span>
<span class="line"><span>$ export CRIO_VERSION=1.24</span></span></code></pre></div><p>完成后，运行以下命令集以添加 CRI-O Kubic 仓库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;deb https://download.opensuse.org/repositories/devel:/kubic:/libcontainers:/stable/$OS/ /&quot;| sudo tee /etc/apt/sources.list.d/devel:kubic:libcontainers:stable.list</span></span>
<span class="line"><span>$ echo &quot;deb http://download.opensuse.org/repositories/devel:/kubic:/libcontainers:/stable:/cri-o:/$CRIO_VERSION/$OS/ /&quot;|sudo tee /etc/apt/sources.list.d/devel:kubic:libcontainers:stable:cri-o:$CRIO_VERSION.list</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Set-Crio-Repository-Ubuntu-Linux.png" alt=""></p><p>此后，为 CRI-O 仓库导入 GPG 密钥：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -L https://download.opensuse.org/repositories/devel:kubic:libcontainers:stable:cri-o:$CRIO_VERSION/$OS/Release.key | sudo apt-key add -</span></span>
<span class="line"><span>$ curl -L https://download.opensuse.org/repositories/devel:/kubic:/libcontainers:/stable/$OS/Release.key | sudo apt-key add -</span></span></code></pre></div><p>这会产生如下输出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Import-GPG-Keys-for-Crio-Repository-Ubuntu-Linux.png" alt=""></p><p>再次更新包索引，使系统与新添加的 CRI-O Kubic 仓库同步：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt update</span></span></code></pre></div><h3 id="步骤-3-在-ubuntu-22-04-上安装-cri-o" tabindex="-1">步骤 3：在 Ubuntu 22.04 上安装 CRI-O <a class="header-anchor" href="#步骤-3-在-ubuntu-22-04-上安装-cri-o" aria-label="Permalink to “步骤 3：在 Ubuntu 22.04 上安装 CRI-O”">​</a></h3><p>添加仓库后，使用 APT 包管理器安装 CRI-O 和运行时客户端：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install cri-o cri-o-runc -y</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Apt-Install-Crio-Ubuntu-Linux.png" alt=""></p><p>安装后，启动并启用 CRI-O 守护程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl start crio</span></span>
<span class="line"><span>$ sudo systemctl enable crio</span></span></code></pre></div><p>接下来，验证 CRI-O 服务是否正在运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl status crio</span></span></code></pre></div><p>你应该看到以下输出，表明 CRI-O 服务正在按预期运行：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Start-Enable-Crio-Service-Ubuntu.png" alt=""></p><h3 id="步骤-4-为-cri-o-安装-cni-插件" tabindex="-1">步骤 4：为 CRI-O 安装 CNI 插件 <a class="header-anchor" href="#步骤-4-为-cri-o-安装-cni-插件" aria-label="Permalink to “步骤 4：为 CRI-O 安装 CNI 插件”">​</a></h3><p>接下来，你需要安装 CNI（<ruby>容器网络接口<rt>Container Network Interface</rt></ruby>）以及 CNI 插件。请记住，环回和桥接配置已启用并且足以使用 CRI-O 运行 <ruby>容器荚<rt>Pod</rt></ruby>：</p><p>因此，要安装 CNI 插件，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install containernetworking-plugins -y</span></span></code></pre></div><p>安装后，编辑 CRI-O 配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nano /etc/crio/crio.conf</span></span></code></pre></div><p>取消注释 <code>network_dir</code> 和 <code>plugin_dirs</code> 部分，并在 <code>plugin_dirs</code> 下添加 <code>/usr/lib/cni/</code>。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Crio-Conf-Network-Plugins-Directory-Ubuntu.png" alt=""></p><p>保存更改并退出配置文件。</p><p>接下来，重启 CRIO 服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl restart crio</span></span></code></pre></div><h3 id="步骤-5-安装-cri-o-工具" tabindex="-1">步骤 5：安装 CRI-O 工具 <a class="header-anchor" href="#步骤-5-安装-cri-o-工具" aria-label="Permalink to “步骤 5：安装 CRI-O 工具”">​</a></h3><p>此外，你还需要安装 <code>cri-tools</code> 包，它提供了 <code>crictl</code> 命令行程序，用于交互和管理容器和 pod。</p><p>为此，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install -y cri-tools</span></span></code></pre></div><p>安装后，确认 <code>crictl</code> 的版本和 <code>RunTimeVersion</code> 如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo crictl --runtime-endpoint unix:///var/run/crio/crio.sock version</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Crictl-Crio-Version-Check-Ubuntu-Linux.png" alt=""></p><p>一定要检查 CRI-O 是否准备好使用以下命令部署容器荚：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo crictl info</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Crictl-Info-Command-Ubuntu.png" alt=""></p><p><code>crictl</code> 命令提供自动补全功能，让你可以通过按 <code>TAB</code> 键自动补全命令。要启用命令补全，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo su -</span></span>
<span class="line"><span></span></span>
<span class="line"><span># crictl completion &gt; /etc/bash_completion.d/crictl</span></span></code></pre></div><p>然后重新加载当前的 Bash 会话：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># source ~/.bashrc</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Enable-Bash-Completion-Crictl-Command-Ubuntu.png" alt=""></p><p>要使用自动补全功能，你需要注销或启动新的终端会话。然后只需键入 <code>crictl</code> 命令并按 <code>TAB</code> 键即可查看所有选项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ crictl</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Crictl-Command-Options-Ubuntu.png" alt=""></p><h3 id="步骤-6-使用-crictl-程序创建容器荚" tabindex="-1">步骤 6：使用 crictl 程序创建容器荚 <a class="header-anchor" href="#步骤-6-使用-crictl-程序创建容器荚" aria-label="Permalink to “步骤 6：使用 crictl 程序创建容器荚”">​</a></h3><p>至此，CRI-O 已完全安装和配置并准备好启动容器荚。在本节中，我们将在容器荚中创建一个 Apache Web 服务器并确认它是否正在处理请求。</p><p>首先，我们将使用容器荚配置文件设置一个沙箱或隔离环境，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nano apache_sandbox.json</span></span></code></pre></div><p>然后我们将以下配置添加到文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;metadata&quot;: {</span></span>
<span class="line"><span>        &quot;name&quot;: &quot;apache-sandbox&quot;,</span></span>
<span class="line"><span>        &quot;namespace&quot;: &quot;default&quot;,</span></span>
<span class="line"><span>        &quot;attempt&quot;: 1,</span></span>
<span class="line"><span>        &quot;uid&quot;: &quot;hdishd83djaidwnduwk28bcsb&quot;</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    &quot;linux&quot;: {</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    &quot;log_directory&quot;: &quot;/tmp&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>保存并退出。接下来使用以下命令创建容器荚。这会打印出很长的字母数字，它是容器荚 ID。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo crictl runp apache_sandbox.json</span></span></code></pre></div><p>要确认容器荚已创建，请运行命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo crictl pods</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Crictl-Pods-Status-Ubuntu.png" alt=""></p><p>要检索有关创建的容器荚的更多信息，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo crictl inspectp --output table 05ba2f0704f22</span></span></code></pre></div><p>这将打印出 ID、名称、UID、命名空间、创建日期、内部 IP 等详细信息。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Crictl-Inspect-Pod-Ubuntu-Linux.png" alt=""></p><h3 id="步骤-7-在容器荚中创建容器" tabindex="-1">步骤 7：在容器荚中创建容器 <a class="header-anchor" href="#步骤-7-在容器荚中创建容器" aria-label="Permalink to “步骤 7：在容器荚中创建容器”">​</a></h3><p>这部分中，我们将在容器荚中创建一个 Apache Web 服务器容器。因此，使用 <code>crictl</code> 程序从 Docker Hub 拉取 Apache Web 服务器镜像：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo crictl pull httpd</span></span></code></pre></div><p>你可以如图所示验证拉取的镜像：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo crictl images</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Crictl-pull-image-ubuntu.png" alt=""></p><p>接下来，我们将为 Apache Web 服务器定义一个容器配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nano container_apache.json</span></span></code></pre></div><p>复制并粘贴以下代码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;metadata&quot;: {</span></span>
<span class="line"><span>      &quot;name&quot;: &quot;apache&quot;</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>  &quot;image&quot;:{</span></span>
<span class="line"><span>      &quot;image&quot;: &quot;httpd&quot;</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>  &quot;log_path&quot;:&quot;apache.0.log&quot;,</span></span>
<span class="line"><span>  &quot;linux&quot;: {</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>保存并退出配置文件。</p><p>最后，要将容器连接到之前创建的沙盒容器荚，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo crictl create 05ba2f0704f22 container_apache.json apache_sandbox.json</span></span></code></pre></div><p>这会向终端输出一长串字母数字 ID。请记下此 ID。</p><p>最后，使用 ID 启动 Apache Web 服务器容器，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo crictl start 37f4d26510965452aa918f04d629f5332a1cd398d4912298c796942e22f964a7</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Create-Container-Inside-Pod-Ubuntu-Linux.png" alt=""></p><p>要检查容器状态，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo crictl ps</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Pods-Status-Crictl-Command-Ubuntu.png" alt=""></p><p>要验证 Apache Web 服务器是否正在运行，请使用 <code>curl</code> 命令和容器荚的内部 ID 向 Web 服务器发送 HTTP 请求：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -I 10.85.0.2</span></span></code></pre></div><p>以下输出确认 Web 服务器正在运行：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Curl-Command-Httpd-Pod-Ubuntu.png" alt=""></p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>这就是全部的指南。我们已经在 Ubuntu 22.04 上成功安装了 CRI-O，并继续创建容器荚和容器。欢迎你提出意见和反馈。</p><hr>`,107)),n("p",null,[s[1]||(s[1]=i("via: ",-1)),t(a,{href:"https://www.linuxtechi.com/install-crio-container-runtime-on-ubuntu/"},{default:e(()=>[...s[0]||(s[0]=[i("https://www.linuxtechi.com/install-crio-container-runtime-on-ubuntu/",-1)])]),_:1})]),n("p",null,[s[6]||(s[6]=i("作者：",-1)),t(a,{href:"https://www.linuxtechi.com/author/james/"},{default:e(()=>[...s[2]||(s[2]=[i("James Kiarie",-1)])]),_:1}),s[7]||(s[7]=i(" 选题：",-1)),t(a,{href:"https://github.com/lkxed/"},{default:e(()=>[...s[3]||(s[3]=[i("lkxed",-1)])]),_:1}),s[8]||(s[8]=i(" 译者：",-1)),t(a,{href:"https://github.com/geekpi"},{default:e(()=>[...s[4]||(s[4]=[i("geekpi",-1)])]),_:1}),s[9]||(s[9]=i(" 校对：",-1)),t(a,{href:"https://github.com/wxy"},{default:e(()=>[...s[5]||(s[5]=[i("wxy",-1)])]),_:1})]),n("p",null,[s[12]||(s[12]=i("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[10]||(s[10]=[i("LCTT",-1)])]),_:1}),s[13]||(s[13]=i(" 原创编译，",-1)),t(a,{href:"https://linux.cn/"},{default:e(()=>[...s[11]||(s[11]=[i("Linux中国",-1)])]),_:1}),s[14]||(s[14]=i(" 荣誉推出",-1))])])}const x=l(r,[["render",h]]);export{y as __pageData,x as default};
